#include <stdio.h>



int main(void) {
    for (char a = 'X'; a <= 'Z'; a++)
        for (char b = 'X'; b <= 'Z'; b++)
            for (char c = 'X'; c <= 'Z'; c++)
                if (a != b && a != c && b != c && a != 'X' && c != 'X' && c != 'Z')
                    printf("A-%c\nB-%c\nC-%c\n", a, b, c);
    return 0;
}
